const CLOZE4=[['Jag ___ svenska på SFI.','läser',['läser','äter','bor'],'läser + språk'],['I går ___ jag hemma.','var',['var','är','ska'],'preteritum av vara = var'],['Jag har ___ min läxa.','gjort',['gjort','göra','gör'],'supinum efter har'],['Hon ___ inte kaffe.','dricker',['dricker','dricka','drack'],'presens = dricker'],['Vi ___ bussen till skolan.','tar',['tar','tarit','gör'],'ta bussen'],['Det ___ i dag.','regnar',['regnar','regn','regnade'],'väder: det regnar'],['Min syster ___ Sara.','heter',['heter','namn','har'],'heta = heter'],['Ett stort ___ står där.','hus',['hus','bilar','bok'],'ett hus'],['Jag vill ___ svenska.','lära',['lära','lärde','lärt'],'vill + infinitiv'],['På fredagar ___ jag ledig.','är',['är','varit','har'],'vara → är']];
const oldGetQuestion4=legacyGetQuestion4;
function getQuestion(mode){if(locale4()==='ru')return oldGetQuestion4(mode);if(mode==='mixed')mode=shuffle(['fillBlank','verbForms','articles','alphabet','weekdays','months','listening','fixMistake'])[0];
 if(mode==='translation'||mode==='writeWord'){const items=WORDS.filter(w=>w.en&&w.uk);let w=shuffle(items)[0];let others=shuffle(items.filter(x=>x.word!==w.word)).slice(0,3);return mode==='translation'?choice(`${w.word} → ?`,locMeaning4(w),others.map(locMeaning4),w.id,`${w.word} — ${locMeaning4(w)}`):{type:'type',question:`${locMeaning4(w)} → 🇸🇪`,answer:w.word,wordId:w.id,why:`${w.word} — ${locMeaning4(w)}`}}
 if(['fillBlank','dialogues','sentences','fixMistake','readText'].includes(mode)){const [sentence,correct,opts,why]=shuffle(CLOZE4)[0];return choice(`${t('formWord')}: ${sentence}`,correct,opts.filter(x=>x!==correct),null,why)}
 if(['weekdays','months'].includes(mode)){const arr=mode==='weekdays'?DAYS3:MONTHS3;const k=Math.floor(Math.random()*arr.length),row=arr[k],after=arr[(k+1)%arr.length];return choice(`${t(mode==='weekdays'?'daysPractice':'monthsPractice')}: ${txt4('', 'What comes after','Vad kommer efter','Що йде після')} ${row[0]}?`,after[0],shuffle(arr.filter(x=>x[0]!==after[0])).slice(0,3).map(x=>x[0]),null,`${row[0]} → ${after[0]}`)}
 if(mode==='alphabet'){let [letter,ipa,word]=shuffle(ALPHABET3)[0];return choice(`${t('alphabetHub')}: ${word} → ?`,letter,shuffle(ALPHABET3.filter(x=>x[0]!==letter)).slice(0,3).map(x=>x[0]),null,`${word} → ${letter} · ${ipa}`)}
 if(mode==='articles'){const nouns=WORDS.filter(w=>w.type==='noun'&&w.article);const w=shuffle(nouns)[0];return choice(`${t('articles')}: ${w.word}`,w.article,[w.article==='en'?'ett':'en'],w.id,`${w.article} ${w.word}`)}const q=oldGetQuestion4(mode);if(q&&q.why)q.why=t('lessonQuizTip');return q;}
const oldStartQuiz4=legacyStartQuiz4;
function startQuiz(mode='mixed',lesson=null,forReview=false){if(locale4()==='ru')return oldStartQuiz4(mode,lesson,forReview);
 let questions=[];if(mode==='book'){const b=BOOKS.find(x=>x.id===lesson);if(b){const list=b.text.split(/(?<=[.!?])\s+/).filter(x=>x.trim().split(' ').length>3),distractors=BOOKS.filter(other=>other.id!==b.id).flatMap(other=>other.text.split(/(?<=[.!?])\s+/));questions=list.slice(0,7).map((sentence,i)=>{const wrong=shuffle(distractors.filter(x=>x!==sentence)).slice(0,3);return choice(`${t('textPractice')} · ${b.title}: ${txt4('', 'Choose a sentence from the story','Välj en mening från berättelsen','Обери речення з оповідання')}`,sentence,wrong,null,t('readSwedish'))})}}else if(mode==='topic'){let words=shuffle(WORDS.filter(w=>w.category===lesson));questions=words.slice(0,20).map((w,i)=>{let answer=w.word;return choice(`${locCategory4(lesson)} · ${t('wordTranslation')}: ${w.en&&w.uk?locMeaning4(w):t('pronounce')}`,answer,shuffle(words.filter(x=>x!==w)).slice(0,3).map(x=>x.word),w.id,w.en&&w.uk?locMeaning4(w):t('listenRepeat'))})}else if(lesson){const l=LESSONS.find(x=>x.id===lesson);if(l){let sv=l.examples.map(x=>x.sv);for(const s of sv){let words=s.replace(/[,.!?;:]/g,'').split(/\s+/).filter(x=>x.length>2);let correct=words[Math.floor(words.length/2)];let wrong=shuffle(sv.filter(x=>x!==s).flatMap(x=>x.replace(/[,.!?;:]/g,'').split(/\s+/).filter(x=>x.length>2&&x!==correct)));questions.push(choice(`${t('formWord')}: ${s.replace(correct,'___')}`,correct,wrong.slice(0,3),null,s))}questions=shuffle(questions)}}else{questions=Array.from({length:20},()=>getQuestion(mode))}
 if(!questions.length){toast(t('noDue'));return}quiz={active:true,finished:false,mode,lesson,questions,index:0,score:0,answered:false,selected:[],latest:null};navigate('practice');}
