function searchNow(value){const q=String(value||'').trim().toLocaleLowerCase(),el=$('#search-results');if(!el)return;if(!q){el.classList.add('hidden');el.innerHTML='';return}
 const contains=(s)=>String(s||'').toLocaleLowerCase().includes(q);
 const topics=topicNames3().filter(n=>contains(n)||contains(locCategory4(n))).slice(0,5);
 const lessons=LESSONS.filter(l=>[l.title,locLesson4(l),l.description,...l.examples.map(x=>x.sv)].some(contains)).slice(0,6);
 const books=BOOKS.filter(b=>[b.title,b.translation,b.text].some(contains)).slice(0,4);
 const words=WORDS.filter(w=>[w.word,w.ru,w.en,w.uk,w.inf,w.pre,w.past,w.sup,w.category,locCategory4(w.category),w.example].some(contains)).slice(0,8);
 const row=(target,param,icon,name,description)=>`<button type="button" class="search-result" data-nav="${target}" data-param="${esc(param)}"><span class="emo" aria-hidden="true">${icon}</span><span><strong>${esc(name)}</strong><small>${esc(description)}</small></span></button>`;
 el.innerHTML=[...topics.map(x=>row('topic',x,'🗂️',locCategory4(x),t('topics'))),...lessons.map(x=>row('lesson',x.id,x.emoji,locLesson4(x),`SFI ${x.level}`)),...books.map(x=>row('book',x.id,x.emoji,x.title,`SFI ${x.level}`)),...words.map(x=>row('word',x.id,x.emoji,wordLabel(x),locMeaning4(x)))].join('')||`<div class="serp-empty">${esc(t('noResults'))}</div>`;el.classList.remove('hidden');}
function renderDictionary(){let rows=filteredWords(),part=rows.slice(0,dictFilter.limit),cats=availableCategories();return title(t('wordCount'),`${t('wordExplain')} · ${WORDS.length} ${t('words')}`)+`<div class="dict-shortcuts"><button class="pill" data-nav="alphabet">🔤 ${esc(t('alphabetHub'))}</button><button class="pill" data-nav="topics">🗂️ ${esc(t('topics'))}</button><button class="pill" data-nav="rules">📜 ${esc(t('rulesHub'))}</button></div><div class="filters-bar"><input class="search-input" id="dict-search" value="${esc(dictFilter.text)}" autocomplete="off" placeholder="${esc(t('searchWords'))}" aria-label="${esc(t('searchWords'))}"><select class="form-select" id="dict-kind" aria-label="${esc(t('all'))}">${[['all',t('all')],['verb',t('verbs')],['noun',t('nouns')],['other',t('other')]].map(([v,n])=>`<option value="${v}" ${dictFilter.kind===v?'selected':''}>${esc(n)}</option>`).join('')}</select><select class="form-select" id="dict-group" aria-label="${esc(t('allGroups'))}">${[['all',t('allGroups')],['1','1'],['2A','2A'],['2B','2B'],['3','3'],['4','4']].map(([v,n])=>`<option value="${v}" ${dictFilter.group===v?'selected':''}>${esc(n)}</option>`).join('')}</select></div><div class="dict-split"><div class="filter-pills"><button class="pill ${!dictFilter.fav?'active':''}" data-action="toggle-fav" data-fav="false">${esc(t('showAll'))}</button><button class="pill ${dictFilter.fav?'active':''}" data-action="toggle-fav" data-fav="true">⭐ ${esc(t('onlyFav'))}</button></div><select id="dict-category" class="form-select" aria-label="${esc(t('allThemes'))}"><option value="all">${esc(t('allThemes'))}</option>${cats.map(c=>`<option value="${esc(c)}" ${dictFilter.category===c?'selected':''}>${esc(locCategory4(c))}</option>`).join('')}</select></div><p class="vocab-counter">${part.length} / ${rows.length} ${esc(t('words'))}</p>${part.length?`<div class="words-grid">${part.map(wordEntry).join('')}</div>`:`<div class="empty-state"><div class="big">🔎</div><h3>${esc(t('noResults'))}</h3></div>`}${rows.length>dictFilter.limit?`<div class="list-footer"><button class="btn secondary" data-action="dict-more">${esc(t('more'))} ↓</button></div>`:''}`}
