const videoLevelMatch=(v)=>v.level.includes(state.settings.level);
function renderVideos(){const vids=[...MORE_VIDEOS].sort((a,b)=>Number(videoLevelMatch(b))-Number(videoLevelMatch(a)));return title(t('videos'),t('videosIntro'))+`<div class="notice">🎬 ${esc(t('vidNote'))}</div><div class="video-grid">${vids.map((v,i)=>`<article class="video-card ${videoLevelMatch(v)?'level-match':''}"><a class="video-main" href="${esc(v.url)}" target="_blank" rel="noopener noreferrer" aria-label="${esc(v.name)}"><div class="video-art tone-${i%6}"><span>${v.emoji}</span><span class="play-mark">▶</span></div><div class="video-body"><div class="video-meta"><span class="chip">SFI ${esc(v.level)}</span>${videoLevelMatch(v)?`<span class="mini-recommended">★ ${esc(pT('levelHint'))}</span>`:''}</div><h3>${esc(v.name)}</h3><p>${esc(txt4('Шведская речь: учись воспринимать настоящие диалоги на слух.','Swedish listening: practise with real spoken conversations.','Svensk hörförståelse: öva med talade dialoger.','Шведське аудіювання: тренуйся на живих діалогах.'))}</p><strong class="vid-link">${esc(t('watch'))} ↗</strong></div></a><div class="video-tools"><button class="btn small ghost" data-action="watched" data-id="${esc(v.id)}">${state.videos.includes(v.id)?'✓ '+esc(t('watched')):esc(t('markWatched'))}</button>${v.question?`<button class="btn small secondary" data-action="video-quiz" data-id="${esc(v.id)}">🧠 ${esc(t('quiz'))}</button>`:''}</div></article>`).join('')}</div>`}
function avatarMarkup(kind='small'){const avatar=state.profile?.avatar;const name=state.profile?.name||user?.name||t('guest');return avatar&&/^data:image\/(jpeg|png|webp);base64,/.test(avatar)?`<img class="user-image" src="${esc(avatar)}" alt="${esc(name)}">`:((kind==='top'||kind==='big')?`<img class="user-image" src="./assets/avatars/pippi-cartoon.png" alt="Pippi Långstrump">`:`<span class="avatar-initial">${esc(name[0]?.toLocaleUpperCase()||'👤')}</span>`)}
function renderNav(){const mk=([key,ico])=>`<button type="button" class="nav-link ${route===key||(route==='book'&&key==='books')||(route==='topic'&&key==='topics')?'active':''}" data-nav="${key}"><span class="nav-glyph">${ico}</span><span class="nav-text">${esc(t(key))}</span></button>`;$('#sidebar-nav').innerHTML=NAV4.slice(0,6).map(mk).join('');$('#sidebar-learn').innerHTML=NAV4.slice(6).map(mk).join('')+`<button class="nav-link ${route==='cheats'?'active':''}" data-nav="cheats"><span class="nav-glyph">🧾</span><span class="nav-text">${esc(pT('cheats'))}</span></button><button class="nav-link ${route==='numbers'?'active':''}" data-nav="numbers"><span class="nav-glyph">🔢</span><span class="nav-text">${esc(pT('numbers'))}</span></button>`;$('#mobile-nav').innerHTML=mainRoutes4.map(([key,ico])=>`<button type="button" class="${route===key?'active':''}" data-nav="${key}" aria-label="${esc(t(key))}"><span class="i">${ico}</span><span>${esc(t(key))}</span></button>`).join('')+`<button type="button" class="mobile-more" id="bottom-menu-open" aria-label="${esc(t('subsections'))}"><span class="i">☰</span><span>${esc(t('subsections'))}</span></button>`;const name=state.profile?.name||user?.name||t('guest');$('#sidebar-profile').innerHTML=`<span class="small-avatar">${avatarMarkup()}</span><span class="nav-account-name"><strong>${esc(name)}</strong><small>🏆 ${esc(t('accountRank'))} ${accountLevel3()}</small></span>`;$('#profile-top').innerHTML=avatarMarkup('top')}
function renderProfile(){const name=state.profile?.name||user?.name||t('guest'),xp=accountProgress3();return title(t('profileTitle'),user?t('savedAccount'):pT('guestExplain'))+`<div class="profile-identity"><section class="profile-person"><div class="big-avatar">${avatarMarkup('big')}</div><div class="identity-copy"><h2>${esc(name)}</h2><p>${esc(user?.email||t('guestMode'))}</p><span class="chip">🇸🇪 SFI ${esc(state.settings.level)}</span></div></section><section class="profile-level"><span class="rank-emoji">🏆</span><div><h2>${esc(t('accountRank'))} ${accountLevel3()}</h2><p>${state.xp} XP · ${xp}/500</p></div><div class="progress-track"><div class="progress-fill" style="width:${xp/5}%"></div></div></section></div><section class="content-panel profile-edit"><h3>✏️ ${esc(pT('personal'))}</h3><div class="edit-inline"><label for="profile-name-edit">${esc(pT('nameEdit'))}</label><input id="profile-name-edit" type="text" class="form-input" maxlength="70" value="${esc(state.profile?.name||user?.name||'')}"><button class="btn small" data-action="save-profile-name">${esc(pT('saveName'))}</button></div><div class="avatar-actions"><label for="profile-photo-file" class="btn secondary small file-select">📷 ${esc(pT('uploadPhoto'))}<input id="profile-photo-file" type="file" accept="image/jpeg,image/png,image/webp" hidden></label>${state.profile?.avatar?`<button class="btn ghost small" data-action="remove-photo">${esc(pT('removePhoto'))}</button>`:''}</div></section><section class="stats-grid">${stat('🔥',streak(),t('dayStreak'),'orange')}${stat('🎓',state.completed.length,t('lessonCount'),'purple')}${stat('🧠',state.known.length,t('knownWords'),'mint')}${stat('📚',(state.booksRead||[]).length,t('booksRead'),'pink')}</section><div class="profile-grid"><section class="content-panel"><h3>🗓️ ${esc(t('practiceActivity'))}</h3>${heatmap()}</section><section class="content-panel"><h3>⚙️ ${esc(t('settings'))}</h3><div class="settings-row"><b>${esc(t('interfaceLang'))}</b><select class="form-select" id="profile-lang">${[['ru','Русский'],['en','English'],['sv','Svenska'],['uk','Українська']].map(([k,v])=>`<option value="${k}" ${locale4()===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="settings-row"><b>${esc(t('sfiLevel'))}</b><select class="form-select" id="profile-level">${'ABCD'.split('').map(l=>`<option value="${l}" ${state.settings.level===l?'selected':''}>SFI ${l}</option>`).join('')}</select></div><p class="micro-note">${esc(user?t('savedAccount'):t('savedGuest'))}</p></section></div><section class="content-panel auth-teaser"><h3>🔐 ${esc(user?t('profile'):t('register'))}</h3><p>${esc(user?t('savedAccount'):pT('guestExplain'))}</p>${user?`<button class="btn ghost small" data-action="logout">${esc(t('logout'))}</button>`:`<div class="split"><button class="btn small" data-action="auth" data-mode="register">${esc(t('register'))}</button><button class="btn secondary small" data-action="auth" data-mode="login">${esc(t('login'))}</button></div>`}</section>`}



const SWEDISH_LETTER_NAMES={A:'a',B:'be',C:'se',D:'de',E:'e',F:'eff',G:'ge',H:'hå',I:'i',J:'ji',K:'kå',L:'ell',M:'emm',N:'enn',O:'o',P:'pe',Q:'ku',R:'err',S:'ess',T:'te',U:'u',V:'ve',W:'dubbelve',X:'eks',Y:'y',Z:'säta','Å':'å','Ä':'ä','Ö':'ö'};
let svVoices=[];
if('speechSynthesis' in window){svVoices=speechSynthesis.getVoices();speechSynthesis.addEventListener?.('voiceschanged',()=>{svVoices=speechSynthesis.getVoices()})}
function speak(text){if(!('speechSynthesis' in window)){toast(pT('audioError'));return}try{const api=speechSynthesis;api.cancel();const u=new SpeechSynthesisUtterance(String(text));u.lang='sv-SE';u.rate=.8;u.pitch=1;const voices=api.getVoices();const sv=voices.find(x=>x.lang.toLowerCase()==='sv-se')||voices.find(x=>x.lang.toLowerCase().startsWith('sv'));if(sv)u.voice=sv;else if(voices.length){toast(pT('audioError'));return}u.onerror=()=>toast(pT('audioError'));api.speak(u)}catch(_){toast(pT('audioError'))}}
function speakLetter3(letter){speak(SWEDISH_LETTER_NAMES[letter]||letter)}
function profilePhotoChange(file){if(!file)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)||file.size>6*1024*1024){toast(pT('avatarError'));return}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const size=240,c=document.createElement('canvas');c.width=size;c.height=size;const ctx=c.getContext('2d');const crop=Math.min(img.width,img.height),x=(img.width-crop)/2,y=(img.height-crop)/2;ctx.drawImage(img,x,y,crop,crop,0,0,size,size);const val=c.toDataURL('image/jpeg',.78);mutate(()=>{state.profile=state.profile||{};state.profile.avatar=val;touch()});render();toast(pT('profileSave'))};img.onerror=()=>toast(pT('avatarError'));img.src=reader.result};reader.onerror=()=>toast(pT('avatarError'));reader.readAsDataURL(file)}
document.addEventListener('change',event=>{if(event.target?.id==='profile-photo-file')profilePhotoChange(event.target.files?.[0])});
document.addEventListener('click',event=>{const b=event.target?.closest?.('[data-action="save-profile-name"],[data-action="remove-photo"]');if(!b)return;event.preventDefault();event.stopImmediatePropagation();if(b.dataset.action==='save-profile-name'){const value=String(document.getElementById('profile-name-edit')?.value||'').trim().slice(0,70);if(!value)return;mutate(()=>{state.profile=state.profile||{};state.profile.name=value;touch()})}else{mutate(()=>{state.profile=state.profile||{};state.profile.avatar='';touch()})}render();toast(pT('profileSave'))},true);


