document.addEventListener('click',e=>{const el=e.target?.closest?.('[data-action="video-quiz"]');if(!el)return;e.preventDefault();e.stopImmediatePropagation();const v=MORE_VIDEOS.find(x=>x.id===el.dataset.id);if(!v?.question)return;const question=choice(v.question,v.answer,v.wrong,null,txt4('Вопрос по описанию выпуска UR Play. Чтобы проверить аудирование, сначала посмотри видео.','Question based on the UR Play episode description. Watch the video first to practise listening.','Frågan bygger på avsnittsbeskrivningen hos UR Play. Titta först på videon.','Запитання за описом випуску UR Play. Спершу переглянь відео.'));quiz={active:true,finished:false,mode:'mixed',lesson:null,questions:[question],index:0,score:0,answered:false,selected:[],latest:null};navigate('practice')},true);


